WITH ards AS (SELECT subject_id, hadm_id, (charttime - intime) AS length_of_stay FROM admissions JOIN patients ON admissions.subject_id = patients.subject_id WHERE gender = 2 AND age BETWEEN 40 AND 50 AND ards_severity IS NOT NULL), lab_events AS (SELECT subject_id, COUNT(*) AS num_lab_events FROM labevents JOIN ards ON labevents.subject_id = ards.subject_id WHERE itemid IN (SELECT itemid FROM d_labitems WHERE category = 'critical') AND charttime <= (SELECT MAX(charttime) FROM chartevents WHERE eventtype = 'chart' AND subject_id IN (SELECT subject_id FROM ards)) GROUP BY subject_id), mortality AS (SELECT subject_id, (SELECT COUNT(*) FROM admissions WHERE hadm_id = ards.hadm_id AND deathtime IS NOT NULL) AS num_deaths FROM ards), avg_lab_events AS (SELECT subject_id, AVG(num_lab_events) AS avg_lab_event_rate FROM lab_events GROUP BY subject_id), avg_mortality AS (SELECT subject_id, AVG(num_deaths) AS avg_mortality_rate FROM mortality GROUP BY subject_id) SELECT percentile_cont(0.75) within GROUP (ORDER BY avg_lab_event_rate) AS lab_event_threshold, percentile_cont(0.75) within GROUP (ORDER BY avg_mortality_rate) AS mortality_threshold FROM avg_lab_events, avg_mortality;